static constexpr int g_twFixupCount = 442;

inline const char* LookupTwFixup(const char* key) {
    if (!key) return nullptr;
    for (int i = 0; i < g_twFixupCount; ++i) {
        if (strcmp(g_twFixups[i].key, key) == 0)
            return g_twFixups[i].tc_text;
    }
    return nullptr;
}
